import random
from sympy import gcd, mod_inverse
from pwn import remote

def extract_params(filename):
    with open(filename, 'r') as f:
        data = f.read()
    ns = {}
    exec(data, ns)
    # c is bytes, needs to be converted to int
    n = ns['n']
    e = ns['e']
    c_bytes = ns['c']
    if isinstance(c_bytes, int):
        c = c_bytes
    else:
        c = int.from_bytes(c_bytes, 'big')
    return n, e, c

def int_to_bytes(x):
    return x.to_bytes((x.bit_length() + 7) // 8, 'big')

def query_oracle(ciphertext_int):
    conn = remote('crypto.csaw.io', 3000)
    conn.sendline(hex(ciphertext_int).encode())
    recv = conn.recvline().decode().strip()
    if recv.startswith('0x'):
        recv = recv[2:]
    res = int(recv, 16)
    conn.close()
    return res

def main():
    n, e, c = extract_params('/home/ctfplayer/ctf_files/param.py')
    # Step 2: Pick s coprime to n
    while True:
        s = random.randrange(2, n)
        if gcd(s, n) == 1:
            break
    c_prime = (c * pow(s, e, n)) % n
    print(f'Sending c_prime to oracle...')
    m_prime = query_oracle(c_prime)
    s_inv = mod_inverse(s, n)
    m = (m_prime * s_inv) % n
    m_bytes = int_to_bytes(m)
    try:
        sflag = m_bytes.decode('utf-8', errors='ignore')
        if 'csawctf{' in sflag:
            flag = sflag[sflag.index('csawctf{'):sflag.index('}')+1]
            print(f'Flag: {flag}')
        else:
            print('Flag not found. Output:', sflag)
    except Exception as e:
        print('Output could not be decoded:', e)
    print(f'(int) Plaintext: {m}')

if __name__ == '__main__':
    main()

