import requests
import json
import gmpy2
from param import n, e, c

# Use gmpy2 for big integer math
query_url = 'http://crypto.csaw.io/rsa/decrypt'
headers = {'Content-Type': 'application/json'}

def query_oracle(c_):
    data = {'ciphertext': hex(int(c_))[2:]}
    res = requests.post(query_url, headers=headers, json=data)
    j = res.json()
    return int(j['lsb'])

# Use gmpy2.mpz everywhere to avoid OverflowError
def recover_plaintext(c, n, e, oracle, exp_bits=None):
    lower = gmpy2.mpz(0)
    upper = gmpy2.mpz(n)
    c_tmp = gmpy2.mpz(c)
    two_e = gmpy2.powmod(2, e, n)
    if exp_bits is None:
        exp_bits = n.bit_length()
    for i in range(exp_bits):
        c_tmp = (c_tmp * two_e) % n
        lsb = oracle(c_tmp)
        mid = (lower + upper) // 2
        if lsb == 0:
            upper = mid
        else:
            lower = mid
        # Trace progress
        if (i % 16 == 0 or upper - lower == 1):
            approx = hex(int(lower))
            print(f"After {i+1} bits, interval: {int(upper-lower)}; lower: {approx}")
        if upper - lower == 1:
            break
    return int(lower)

if __name__ == '__main__':
    plaintext = recover_plaintext(c, n, e, query_oracle)
    print(f"Recovered plaintext as integer:\n{plaintext}\n")
    hx = hex(plaintext)[2:]
    print(f"Hex: {hx}\n")
    try:
        dec = bytes.fromhex(hx)
        print("UTF-8 decoded:\n", dec.decode('utf-8'))
    except Exception as ex:
        print("Decode error:", ex)
        print("Raw bytes:\n", dec)
